import itertools

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def get_all_strings(n):
    return ["".join(map(str, p)) for p in itertools.product([0, 1], repeat=n)]

def generate_C_S_k(S, n, k):
    C_S_k = set()
    all_strings = get_all_strings(n)
    for T in all_strings:
        if hamming_distance(S, T) == k:
            C_S_k.add(T)
    return C_S_k

# --- Case 1: n=4, k=1 ---
n1, k1 = 4, 1
print(f"--- Testing N={n1}, K={k1} ---")
all_strings_n4 = get_all_strings(n1)
found_non_unique = False
for i in range(len(all_strings_n4)):
    S1 = all_strings_n4[i]
    C1 = generate_C_S_k(S1, n1, k1)
    for j in range(i + 1, len(all_strings_n4)):
        S2 = all_strings_n4[j]
        C2 = generate_C_S_k(S2, n1, k1)

        if C1 == C2:
            print(f"Non-unique found! S1={S1} and S2={S2} give the same set C(S, 1).")
            found_non_unique = True
            break
    if found_non_unique:
        break

if not found_non_unique:
    print(f"No non-unique pairs found for N={n1}, K={k1}.")

print("\n" + "="*30 + "\n")

# --- Case 2: n=5, k=2 ---
n2, k2 = 5, 2
print(f"--- Testing N={n2}, K={k2} ---")
all_strings_n5 = get_all_strings(n2)
found_non_unique = False
for i in range(len(all_strings_n5)):
    S1 = all_strings_n5[i]
    C1 = generate_C_S_k(S1, n2, k2)
    for j in range(i + 1, len(all_strings_n5)):
        S2 = all_strings_n5[j]
        C2 = generate_C_S_k(S2, n2, k2)

        if C1 == C2:
            print(f"Non-unique found! S1={S1} and S2={S2} give the same set C(S, 2).")
            found_non_unique = True
            break
    if found_non_unique:
        break

if not found_non_unique:
    print(f"No non-unique pairs found for N={n2}, K={k2}.")
